 static GameObject MeshObj(string n,List<Vector3> v,List<int> t,Material m,bool col=true){var mesh=new Mesh();mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.uv=v.Select(p=>new Vector2(p.x*.15f,p.z*.15f)).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();string mp=D+"/Mesh"+(serial++)+".asset";AssetDatabase.DeleteAsset(mp);AssetDatabase.CreateAsset(mesh,mp);var g=new GameObject(n);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=m;if(col)g.AddComponent<MeshCollider>().sharedMesh=mesh;return g;}
 static GameObject Lathe(string n,Vector3 p,float[] ys,float[] rs,Material m,int seg=48){var v=new List<Vector3>();var t=new List<int>();for(int j=0;j<ys.Length;j++)for(int i=0;i<=seg;i++){float a=i*Mathf.PI*2/seg;v.Add(p+new Vector3(Mathf.Cos(a)*rs[j],ys[j],Mathf.Sin(a)*rs[j]));if(j>0&&i<seg){int k=j*(seg+1)+i;t.AddRange(new[]{k,k-seg-1,k+1,k+1,k-seg-1,k-seg});}}return MeshObj(n,v,t,m);}
 static GameObject Prop(string token,Vector3 p,float size,float yaw=0){var path=AssetDatabase.FindAssets(token+" t:Prefab",new[]{"Assets/Art/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault();if(path==null)return null;var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));g.transform.rotation=Quaternion.Euler(0,yaw,0);var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);g.transform.localScale*=size/b.size.y;b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);g.transform.position+=p-new Vector3(b.center.x,b.min.y,b.center.z);if(token.Contains("Rock"))foreach(var f in g.GetComponentsInChildren<MeshFilter>())if(!f.GetComponent<Collider>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;return g;}
