 static void Strip(string name,System.Func<float,Vector3> center,float width,Material m,int count=180){var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<=count;i++){float f=i/(float)count;var p=center(f);var d=(center(Mathf.Min(1,f+.001f))-center(Mathf.Max(0,f-.001f))).normalized;var side=new Vector3(d.z,0,-d.x)*width;v.Add(p-side);v.Add(p+side);if(i<count){int k=i*2;t.AddRange(new[]{k,k+2,k+1,k+1,k+2,k+3});}}MeshObj(name,v,t,m);}
 static Vector3 Path(float f){float z=-15+f*51,x=TrailX(z);return new Vector3(x,Height(x,z)+.06f,z);}
