 static float TrailX(float z)=>10*Mathf.Sin((z+15)/51*Mathf.PI*2-.55f)*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(28,36,z)));
 static float Height(float x,float z){float y=.65f;for(int i=0;i<3;i++){float edge=-2+i*12+1.3f*Mathf.Sin(x*.14f+i);float r=TrailX(z);float smooth=5.3f*Mathf.SmoothStep(0,1,Mathf.InverseLerp(edge-3,edge+3,z));float terrace=z>edge?5.3f:0;float near=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.5f,6,Mathf.Abs(x-r)));y+=Mathf.Lerp(terrace,smooth,near);}return y;}
 static float TrailDist(float x,float z)=>Mathf.Abs(x-TrailX(z));
 static void Texture(Material m,string name,Color a,Color b){int n=256;var tx=new Texture2D(n,n);var pixels=new Color[n*n];for(int j=0;j<n;j++)for(int i=0;i<n;i++){float v=.55f*Mathf.PerlinNoise(i*.035f,j*.035f)+.3f*Mathf.PerlinNoise(i*.13f+5,j*.13f+8)+.15f*Mathf.Sin(j*.6f+i*.12f);pixels[j*n+i]=Color.Lerp(a,b,Mathf.Clamp01(v));}tx.SetPixels(pixels);tx.Apply();string p=D+"/"+name+".asset";AssetDatabase.DeleteAsset(p);AssetDatabase.CreateAsset(tx,p);m.mainTexture=tx;m.color=Color.white;EditorUtility.SetDirty(m);}
 static void BuildLandscape(){
 Texture(sand,"Sand brush",new Color(.72f,.55f,.32f),new Color(.96f,.83f,.56f));Texture(grass,"Grass brush",new Color(.24f,.43f,.10f),new Color(.58f,.73f,.24f));
 var water=Mat("Ocean",new Color(.03f,.45f,.65f));var vv=new List<Vector3>();var tt=new List<int>();var colors=new List<Color>();int W=120;for(int j=0;j<=W;j++)for(int i=0;i<=W;i++){float x=-500+i*1000f/W,z=-500+j*1000f/W;vv.Add(new Vector3(x,-.12f,z));float depth=Mathf.Clamp01(Mathf.Max(Coast(x)-z,Mathf.Max(Mathf.Abs(x)-39,z-53))/25);colors.Add(Color.Lerp(new Color(.12f,.79f,.74f),new Color(.035f,.33f,.59f),depth));if(i<W&&j<W){int k=j*(W+1)+i;tt.AddRange(new[]{k,k+W+1,k+1,k+1,k+W+1,k+W+2});}}var ocean=MeshObj("Ocean depth gradient",vv,tt,water,false);var shader=Shader.Find("Lighthouse/Surface");if(shader){water.shader=shader;water.color=Color.white;}ocean.GetComponent<MeshFilter>().sharedMesh.SetColors(colors);
 vv=new List<Vector3>();tt=new List<int>();colors=new List<Color>();int nx=160,nz=180;for(int j=0;j<=nz;j++)for(int i=0;i<=nx;i++){float x=-54+i*108f/nx,z=-38+j*108f/nz;float edge=Mathf.Max(Mathf.Abs(x)/(40+3*Mathf.Sin(z*.15f)),Mathf.Max(0,(z-30)/28));float h=Height(x,z);h=Mathf.Lerp(h,-3,Mathf.SmoothStep(0,1,Mathf.InverseLerp(.86f,1.14f,edge)));if(z<Coast(x)+4.4f)h=Mathf.Min(h,(z-Coast(x))*.15f);vv.Add(new Vector3(x,h,z));float g=Mathf.SmoothStep(0,1,Mathf.InverseLerp(-7,-1,z+1.5f*Mathf.Sin(x*.35f)));float path=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.6f,2.8f,TrailDist(x,z)));float noise=Mathf.PerlinNoise(x*.27f+30,z*.27f+30);var col=Color.Lerp(new Color(.86f,.72f,.46f),Color.Lerp(new Color(.28f,.49f,.12f),new Color(.53f,.69f,.22f),noise),g*(1-path));colors.Add(col);if(i<nx&&j<nz){int k=j*(nx+1)+i;tt.AddRange(new[]{k,k+nx+1,k+1,k+1,k+nx+1,k+nx+2});}}var surface=Mat("Painted terrain blend",Color.white);if(shader)surface.shader=shader;var land=MeshObj("Continuous sand meadow trail",vv,tt,surface);land.GetComponent<MeshFilter>().sharedMesh.SetColors(colors);
 for(int tier=0;tier<3;tier++)for(int i=0;i<17;i++){float x=-39+i*4.8f,z=-2+tier*12+1.3f*Mathf.Sin(x*.14f+tier);if(TrailDist(x,z)<6)continue;float y=.65f+tier*5.3f;var g=Prop("Rock_Medium_"+(1+i%3),new Vector3(x,y-.8f,z+.7f),5.5f+Random.value*1.3f,i*67+tier*33);if(g){g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(1.15f,1,.7f));foreach(var r in g.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int k=0;k<mats.Length;k++)mats[k]=rock;r.sharedMaterials=mats;}}}
