 for(int i=0;i<35;i++){float x=Random.Range(-40f,40f),z=Coast(x)+Random.Range(-5f,7f);Prop("Rock_Medium_"+(i%3+1),new Vector3(x,Mathf.Max(-.5f,Mathf.Min(.65f,(z-Coast(x))*.15f))-.15f,z),Random.Range(.6f,2.7f),i*39);}
