 static GameObject Beam(string n,Vector3 a,Vector3 b,float width,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=(a+b)*.5f;g.transform.up=(b-a).normalized;g.transform.localScale=new Vector3(width,(b-a).magnitude,width);g.GetComponent<Renderer>().sharedMaterial=m;return g;}
