for(int i=0;i<32;i++){float a=i*Mathf.PI*2/32,b=(i+1)*Mathf.PI*2/32;var p=top+new Vector3(Mathf.Cos(a)*7.3f,0,Mathf.Sin(a)*7.3f);var q=top+new Vector3(Mathf.Cos(b)*7.3f,0,Mathf.Sin(b)*7.3f);if(p.z<top.z-6.6f)continue;Beam("Platform fence post",p,p+Vector3.up*1.15f,.16f,wood);Beam("Platform rail",p+Vector3.up*.85f,q+Vector3.up*.85f,.12f,wood);}
